<template>
  <div class="detail-page">
    <header class="page-header"><button @click="router.push('/worlds')">← 返回世界列表</button><div class="header-actions"><el-button v-if="world && !editing" @click="startEditing">编辑世界</el-button><el-button type="primary" :disabled="!world" @click="enterWorld">进入世界</el-button></div></header>
    <main v-loading="worldStore.loading">
      <div v-if="worldStore.error && !world" class="state-card"><p>{{ worldStore.error }}</p><el-button @click="load">重新加载</el-button></div>
      <el-empty v-else-if="!worldStore.loading && !world" description="世界不存在或已被删除" />
      <template v-else-if="world">
        <section v-if="!editing" class="hero-card" :class="accentForWorld(world.id)"><div class="hero-orbit" aria-hidden="true"></div><span class="eyebrow">WORLD PROFILE</span><h1>{{ world.name }}</h1><div class="chips"><span>{{ world.atmosphere || '未设置氛围' }}</span><span>{{ world.scene || '未设置场景' }}</span></div><div class="semantic-grid"><article><b>世界背景</b><p>{{ world.background || '未设置' }}</p></article><article><b>世界规则</b><p>{{ world.rules || '未设置' }}</p></article></div><p v-if="world.sourceDescription" class="source">最初的想法：{{ world.sourceDescription }}</p></section>
        <el-form v-else ref="formRef" :model="form" :rules="rules" label-position="top" class="edit-card">
          <h2>编辑世界语义</h2><el-form-item label="世界名称" prop="name"><el-input v-model="form.name" maxlength="100" /></el-form-item><div class="two-columns"><el-form-item label="氛围"><el-input v-model="form.atmosphere" maxlength="500" /></el-form-item><el-form-item label="场景"><el-input v-model="form.scene" maxlength="1000" /></el-form-item></div><el-form-item label="背景"><el-input v-model="form.background" type="textarea" :rows="4" maxlength="2000" /></el-form-item><el-form-item label="规则"><el-input v-model="form.rules" type="textarea" :rows="4" maxlength="2000" /></el-form-item><div class="edit-actions"><el-button @click="editing=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveWorld">保存</el-button></div>
        </el-form>

        <section class="cast-card"><div class="cast-heading"><div><span class="eyebrow">CAST ORDER</span><h2>参与角色</h2></div><el-button v-if="!world.participantsLocked && !editingRoster" @click="startRosterEdit">替换阵容</el-button></div><el-alert v-if="world.participantsLocked" title="已有互动记录，角色阵容已冻结；世界语义仍可编辑。" type="warning" :closable="false" show-icon />
          <WorldRosterEditor v-if="editingRoster" v-model="selectedCharacters" :characters="characters" />
          <div v-else class="snapshot-list"><article v-for="(participant, index) in visibleWorldParticipants(world)" :key="participant.id"><span class="order">{{ index + 1 }}</span><span class="avatar" :style="{background:participant.character?.avatarColor||'#7c5cff'}">{{ participant.character?.name?.charAt(0)||'角' }}</span><div><h3>{{ participant.character?.name || '未知角色' }}</h3><p>{{ snapshotSummary(participant.character) }}</p></div></article></div>
          <div v-if="editingRoster" class="edit-actions"><el-button @click="editingRoster=false">取消</el-button><el-button type="primary" :loading="savingRoster" :disabled="selectedCharacters.length<2||selectedCharacters.length>4" @click="saveRoster">保存阵容</el-button></div>
        </section>
      </template>
    </main>
  </div>
</template>

<script setup>
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { getCharacterList } from '../api/character'
import { useWorldStore } from '../stores/world'
import WorldRosterEditor from '../components/world/WorldRosterEditor.vue'
import { accentForWorld, buildParticipantPayload, buildWorldSemanticPayload, createWorldForm, eligibleAiCharacters, snapshotSummary, visibleWorldParticipants } from '../utils/worldBuilder'
const route=useRoute();const router=useRouter();const worldStore=useWorldStore();const world=computed(()=>worldStore.currentWorld)
const editing=ref(false),editingRoster=ref(false),saving=ref(false),savingRoster=ref(false),formRef=ref(null);const form=reactive(createWorldForm());const characters=ref([]),selectedCharacters=ref([]);const rules={name:[{required:true,message:'请输入世界名称',trigger:'blur'}]}
function worldId(){const id=Number(route.params.worldId);return Number.isSafeInteger(id)&&id>0?id:null}
async function load(){const id=worldId();if(!id){worldStore.error='无效的World ID';return}try{await worldStore.loadDetail(id)}catch(error){console.error('Load world failed:',error)}}
function startEditing(){Object.assign(form,createWorldForm(world.value));editing.value=true}
async function saveWorld(){const valid=await formRef.value?.validate().catch(()=>false);if(!valid||saving.value)return;saving.value=true;try{await worldStore.update(worldId(),buildWorldSemanticPayload({...form,sourceDescription:world.value.sourceDescription}));editing.value=false;ElMessage.success('世界设定已更新')}catch(error){console.error('Update world failed:',error)}finally{saving.value=false}}
async function startRosterEdit(){if(world.value.participantsLocked)return;try{const response=await getCharacterList('AI');characters.value=eligibleAiCharacters(response.data||response);const byId=new Map(characters.value.map(item=>[item.id,item]));selectedCharacters.value=world.value.participants.map(item=>byId.get(item.sourceCharacterId)).filter(Boolean);editingRoster.value=true}catch(error){console.error('Load characters failed:',error)}}
async function saveRoster(){if(savingRoster.value)return;savingRoster.value=true;try{await worldStore.replaceParticipants(worldId(),buildParticipantPayload(selectedCharacters.value));editingRoster.value=false;ElMessage.success('角色阵容已更新')}catch(error){console.error('Replace roster failed:',error)}finally{savingRoster.value=false}}
function enterWorld(){const id=worldId();if(id)router.push(`/worlds/${id}/interaction`)}
watch(()=>route.params.worldId,()=>{editing.value=false;editingRoster.value=false;worldStore.error='';load()})
onMounted(()=>{worldStore.clearTransient();load()});onUnmounted(()=>{worldStore.clearTransient()})
</script>

<style lang="scss" scoped>
.detail-page{min-height:100vh;color:var(--world-ink);background:radial-gradient(circle at 2% 42%,rgba(131,205,243,.2),transparent 25%),radial-gradient(circle at 98% 23%,rgba(255,171,135,.18),transparent 26%),var(--world-bg)}.page-header,main{width:min(var(--world-content),calc(100% - 48px));margin:auto}.page-header{display:flex;justify-content:space-between;padding:30px 0 20px}.page-header button{color:var(--world-muted);font-weight:700}.header-actions{display:flex;gap:10px}.hero-card,.edit-card,.cast-card,.state-card{position:relative;margin-bottom:22px;padding:32px;border:1px solid var(--world-border);border-radius:var(--world-radius-lg);background:var(--world-surface);box-shadow:var(--world-shadow-sm)}.hero-card{overflow:hidden;border-top:5px solid var(--accent)}.hero-orbit{position:absolute;width:260px;height:190px;right:-50px;top:-85px;border:40px solid var(--accent-soft);border-radius:46% 54% 58% 42%;transform:rotate(16deg)}.accent-sky{--accent:var(--world-sky);--accent-soft:var(--world-sky-soft)}.accent-mint{--accent:var(--world-mint);--accent-soft:var(--world-mint-soft)}.accent-peach{--accent:var(--world-peach);--accent-soft:var(--world-peach-soft)}.eyebrow{position:relative;color:var(--world-primary);font-weight:800;letter-spacing:2px;font-size:11px}h1{position:relative;margin:8px 0 18px;font-size:42px;letter-spacing:-.03em}.chips{position:relative;display:flex;flex-wrap:wrap;gap:8px}.chips span{padding:6px 11px;border-radius:999px;color:var(--world-primary-strong);background:var(--world-primary-soft)}.chips span:nth-child(2){color:#763010;background:var(--world-peach-soft)}.semantic-grid{position:relative;display:grid;grid-template-columns:1.35fr 1fr;gap:14px;margin-top:26px}.semantic-grid article{padding:20px;border:1px solid #e7ecee;border-radius:var(--world-radius-md);background:#fbfdfe}.semantic-grid p,.source,.snapshot-list p{color:var(--world-muted);line-height:1.7;white-space:pre-wrap}.source{position:relative;margin-top:18px;padding:12px;border-radius:var(--world-radius-sm);background:var(--world-mint-soft)}.two-columns{display:grid;grid-template-columns:1fr 1fr;gap:18px}.edit-actions,.cast-heading{display:flex;justify-content:space-between;align-items:center}.edit-actions{justify-content:flex-end;gap:10px;margin-top:15px}.cast-card{border-top:4px solid var(--world-mint)}.snapshot-list{margin-top:18px}.snapshot-list article{display:flex;align-items:center;gap:14px;padding:14px;margin-top:9px;border:1px solid var(--world-border);border-radius:var(--world-radius-md);background:var(--world-surface-blue)}.order{width:25px;color:var(--world-primary);font-weight:800}.avatar{width:46px;height:46px;display:grid;place-items:center;flex:0 0 auto;border:3px solid #fff;border-radius:14px;color:#fff;font-weight:700;box-shadow:0 3px 10px rgba(0,0,0,.1)}.snapshot-list h3,.snapshot-list p{margin:0}.snapshot-list p{margin-top:3px}:deep(.el-form-item__label){color:var(--world-ink);font-weight:700}:deep(.el-input__wrapper),:deep(.el-textarea__inner){color:var(--world-ink);background:#fbfdfe;box-shadow:0 0 0 1px var(--world-border) inset}:deep(.el-button--primary){--el-button-bg-color:var(--world-primary);--el-button-border-color:var(--world-primary);--el-button-hover-bg-color:var(--world-primary-strong);--el-button-hover-border-color:var(--world-primary-strong)}@media(max-width:650px){.page-header,main{width:calc(100% - 32px)}.hero-card,.edit-card,.cast-card{padding:20px}.semantic-grid,.two-columns{grid-template-columns:1fr}.page-header{gap:14px;flex-direction:column}h1{font-size:34px}.hero-orbit{opacity:.5}}
</style>
